#include <stdio.h>
#define INPUTFILE "levels.dat"
int main(void) {
    FILE *inFile;
    double threshold, level;
    int count = 0, above = 0;
    printf("Enter threshold: ");
    scanf("%lf", &threshold);
    inFile = fopen(INPUTFILE, "r");
    if (inFile == NULL) {
        printf("Error: could not open %s\n", INPUTFILE);
        return 1;
    }
    while (fscanf(inFile, "%lf", &level) == 1) {
        count++;
        if (level > threshold)
            above++;
    }
    fclose(inFile);
    printf("%d of %d readings exceed %.2lf m\n", above, count, threshold);
    return 0;
}

#include <stdio.h>
#include <math.h>
#define PI acos(-1.0)
#define OUTPUTFILE "cosTable.dat"
int main(void) {
    FILE *outFile;
    int nRows, k;
    double x;
    printf("Enter number of rows: ");
    scanf("%d", &nRows);
    outFile = fopen(OUTPUTFILE, "w");
    if (outFile == NULL) {
        printf("Error: could not open %s\n", OUTPUTFILE);
        return 1;
    }
    fprintf(outFile, "x cos(x)\n");
    for (k = 1; k <= nRows; k++) {
        x = k * (PI / 2) / nRows;
        fprintf(outFile, "%.3lf %.4lf\n", x, cos(x));
    }
    fclose(outFile);
    printf("Wrote %d rows to %s\n", nRows, OUTPUTFILE);
    return 0;
}

#include <stdio.h>
int main(void) {
    int hours, speed;
    int distance = 0, topSpeed = 0;
    printf("Enter (hours speed) pairs. Enter a non-positive value to stop:\n");
    scanf("%d %d", &hours, &speed);
    while (hours > 0 && speed > 0) {
        distance += hours * speed;
        if (speed > topSpeed)
            topSpeed = speed;
        scanf("%d %d", &hours, &speed);
    }
    printf("Total distance: %d km\n", distance);
    printf("Top speed: %d km/h\n", topSpeed);
    return 0;
}
